export function offerT(
  lang: AppLanguage,
  key: OfferMessageKey,
  vars?: Record<string, string | number>,
): string {
  const raw = OFFER_MESSAGES[lang]?.[key] ?? OFFER_MESSAGES.en[key] ?? key;
  if (!vars) return raw;
  return Object.entries(vars).reduce(
    (s, [k, v]) => s.split('{' + k + '}').join(String(v)),
    raw,
  );
}
